# -*- coding: utf-8 -*-
"""Brasil / Ciências: 8º ano (BNCC EF08CI01–EF08CI16)"""
from br_sci import H, it, nq, num

D = "A que corresponde esta descrição: {v}?"


def f_ohm(R):
    k = R.choice(["i", "v", "r", "p"])
    if k == "i":
        v, r = R.choice([(12, 4), (9, 3), (6, 2), (12, 6), (220, 110), (24, 8), (9, 18), (6, 12)])
        return nq("Uma resistência de %d Ω está ligada a uma pilha de %d V. Qual é a corrente?" % (r, v), v / r, [v * r, r / v, v + r, v - r], "A",
                  "I = U ÷ R = %d ÷ %d = %s A." % (v, r, num(v / r)))
    if k == "v":
        r, i = R.choice([(10, 2), (5, 3), (20, 0.5), (4, 1.5), (100, 0.2), (8, 2)])
        return nq("Por um resistor de %d Ω passa uma corrente de %s A. Qual é a tensão?" % (r, num(i)), r * i, [r / i, r + i, i / r, r * i * 2], "V",
                  "U = R × I = %d × %s = %s V." % (r, num(i), num(r * i)))
    if k == "r":
        v, i = R.choice([(12, 3), (9, 0.5), (220, 2), (6, 0.3), (110, 5), (24, 4)])
        return nq("Uma lâmpada ligada em %d V é percorrida por %s A. Qual é a sua resistência?" % (v, num(i)), v / i, [v * i, i / v, v - i, v / i / 2], "Ω",
                  "R = U ÷ I = %d ÷ %s = %s Ω." % (v, num(i), num(v / i)))
    v, i = R.choice([(220, 5), (110, 10), (12, 2), (220, 10), (127, 2), (220, 0.5)])
    return nq("Um aparelho ligado em %d V puxa %s A. Qual é a sua potência?" % (v, num(i)), v * i, [v / i, v + i, v * i / 1000, v * i * 2], "W",
              "P = U × I = %d × %s = %s W." % (v, num(i), num(v * i)))


def f_kwh(R):
    k = R.choice(["kwh", "custo", "mes", "comp"])
    if k == "kwh":
        w, h = R.choice([(5500, 1), (2000, 2), (1000, 3), (100, 10), (4000, 0.5), (1500, 4), (60, 5)])
        return nq("Um aparelho de %s W fica ligado %s h. Quanta energia ele consome, em kWh?" % (num(w), num(h)), w * h / 1000, [w * h, w / 1000, w * h / 100, w * h / 10000], "kWh",
                  "E = P × t = %s kW × %s h = %s kWh." % (num(w / 1000), num(h), num(w * h / 1000)))
    if k == "custo":
        e, p = R.choice([(150, 0.8), (200, 0.75), (120, 0.9), (250, 0.8), (180, 0.7), (300, 0.85)])
        return nq("Uma casa consumiu %d kWh no mês e a tarifa é de R$ %s por kWh. Quanto custou a energia, em reais?" % (e, num(p, 2).replace(".", ",") if False else ("%.2f" % p).replace(".", ",")), e * p,
                  [e / p, e + p, e * p * 10, e * p / 10], "reais", "%d × %s = %s reais." % (e, ("%.2f" % p).replace(".", ","), num(e * p)))
    if k == "mes":
        w, h, d = R.choice([(5500, 0.5, 30), (100, 5, 30), (2000, 1, 30), (150, 8, 30), (1000, 2, 30), (60, 6, 30)])
        return nq("Um aparelho de %s W é usado %s h por dia durante %d dias. Quanto consome no mês, em kWh?" % (num(w), num(h), d), w * h * d / 1000,
                  [w * h * d, w * h / 1000, w * d / 1000, w * h * d / 100], "kWh", "%s kW × %s h × %d = %s kWh." % (num(w / 1000), num(h), d, num(w * h * d / 1000)))
    a, b, h = R.choice([(60, 9, 6), (100, 15, 5), (40, 6, 8), (75, 10, 4), (60, 8, 10)])
    return nq("Uma lâmpada incandescente de %d W foi trocada por uma de LED de %d W. Quanta energia se economiza em %d h de uso, em Wh?" % (a, b, h), (a - b) * h, [a * h, b * h, a - b, (a + b) * h], "Wh",
              "(%d − %d) × %d = %d Wh." % (a, b, h, (a - b) * h))


